INNER JOIN pcd_file_tag_table ft ON t.tag_id = ft.ft_tag_id
INNER JOIN pcd_file_info_table f ON ft.ft_file_id = f.file_id
WHERE ft.ft_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND ft.ft_file_id = #{file_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND ft.ft_target_type = 'file'
  AND (ft.ft_space_id=#{currentSpaceId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
    OR (#{personalSpace}=true AND ft.ft_space_id IS NULL))
